from __future__ import annotations

import json
import os
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

from core import OfferIndex, SourceError, brl

INDEX = OfferIndex(ttl_seconds=900)

HTML = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buscador Promo do Geissito</title>
<style>
:root{--yellow:#ffd51f;--yellow2:#ffeb5b;--green:#6fca18;--green2:#49a80c;--ink:#10151d;--muted:#64707b;--paper:#f4f6f2;--line:#e2e8df;--red:#ec3345}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,Segoe UI,Arial,sans-serif}.site-header{color:#fff;background:radial-gradient(circle at 80% 15%,#27410e 0,transparent 28%),radial-gradient(circle at 5% 90%,#4a3900 0,transparent 32%),#090d12;padding:0 20px 92px;position:relative;overflow:hidden}.site-header:after{content:"";position:absolute;inset:auto -10% -90px;width:120%;height:150px;background:var(--paper);border-radius:50% 50% 0 0/30% 30% 0 0}.nav{max-width:1180px;margin:auto;min-height:116px;display:flex;align-items:center;justify-content:space-between;gap:24px;position:relative;z-index:1}.brand-logo{width:230px;height:92px;object-fit:contain;object-position:left center}.nav-badge{display:flex;align-items:center;gap:9px;color:#eaf5e4;font-size:.9rem;font-weight:700}.nav-badge:before{content:"";width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 0 6px #6fca1824}.hero{max-width:1180px;margin:26px auto 0;text-align:center;position:relative;z-index:1}.eyebrow{display:inline-flex;align-items:center;gap:8px;padding:8px 13px;border:1px solid #ffffff25;border-radius:999px;color:var(--yellow);background:#ffffff0b;font-weight:800;font-size:.78rem;letter-spacing:.08em;text-transform:uppercase}.hero h1{max-width:880px;margin:22px auto 14px;font-size:clamp(2.45rem,7vw,5.2rem);line-height:.98;letter-spacing:-.055em}.hero h1 span{color:var(--yellow)}.hero p{max-width:650px;margin:0 auto;color:#c8d0d7;font-size:clamp(1rem,2vw,1.18rem);line-height:1.6}.trust{display:flex;justify-content:center;flex-wrap:wrap;gap:18px;margin-top:27px;color:#f1f5ed;font-size:.88rem;font-weight:700}.trust span:before{content:"✓";color:var(--green);font-weight:1000;margin-right:7px}main{max-width:1180px;margin:-54px auto 44px;padding:0 20px;position:relative;z-index:2}.search-panel{background:#fff;border:1px solid var(--line);padding:18px;border-radius:24px;box-shadow:0 22px 60px #111b251a}.searchbox{display:flex;gap:12px;background:#f7f9f6;border:2px solid transparent;padding:8px;border-radius:16px;transition:.2s}.searchbox:focus-within{border-color:var(--green);background:#fff;box-shadow:0 0 0 5px #6fca1817}input{flex:1;border:0;background:transparent;outline:0;font-size:1.08rem;padding:14px 16px;min-width:0;color:var(--ink)}button{border:0;border-radius:12px;background:linear-gradient(135deg,var(--yellow),#f5b900);color:#171300;font-weight:900;padding:0 28px;cursor:pointer;font-size:1rem;box-shadow:0 8px 18px #d9a9002c;transition:transform .18s,box-shadow .18s}button:hover{transform:translateY(-1px);box-shadow:0 11px 24px #d9a9003d}button:disabled{opacity:.6;cursor:wait;transform:none}.examples{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin:14px 0 0}.chip{border:1px solid #d8e1d4;background:#fff;color:#4a5850;padding:8px 13px;border-radius:999px;cursor:pointer;font-size:.88rem;box-shadow:none}.chip:hover{border-color:var(--green);color:#327900}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:40px 0 18px}.section-title h2{font-size:clamp(1.5rem,3vw,2.2rem);margin:0 0 5px;letter-spacing:-.035em}.section-title p{margin:0;color:var(--muted)}#status{color:var(--muted);min-height:24px;font-size:.9rem;font-weight:650}.loading{display:inline-flex;align-items:center;gap:10px}.spinner{width:19px;height:19px;border:3px solid #dce6d7;border-top-color:var(--green);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(255px,1fr));gap:22px}.offer-card{background:#fff;border:1px solid var(--line);border-radius:22px;overflow:hidden;box-shadow:0 7px 24px #13200f0b;display:flex;flex-direction:column;min-width:0;transition:transform .22s,box-shadow .22s,border-color .22s}.offer-card:hover{transform:translateY(-5px);box-shadow:0 18px 38px #13200f17;border-color:#c8d8bf}.photo{width:100%;height:235px;min-height:235px;max-height:235px;display:flex;align-items:center;justify-content:center;position:relative;padding:18px;overflow:hidden;background:linear-gradient(145deg,#fbfcfa,#f0f4ed)}.photo img{display:block;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;object-position:center;mix-blend-mode:multiply}.discount{position:absolute;z-index:2;right:13px;top:13px;background:var(--red);color:#fff;padding:8px 11px;border-radius:999px;font-weight:950;box-shadow:0 6px 15px #d81c3040}.content{padding:18px;display:flex;flex:1;flex-direction:column;min-height:245px;position:relative;z-index:1;background:#fff}.store{align-self:flex-start;color:#377e0c;background:#eff9e8;border:1px solid #d9efcc;padding:5px 8px;border-radius:7px;font-size:.7rem;text-transform:uppercase;font-weight:950;letter-spacing:.07em}.content h2{font-size:1rem;line-height:1.42;margin:11px 0 17px;letter-spacing:-.01em}.prices{margin-top:auto}.old{text-decoration:line-through;color:#8b9690;font-size:.87rem}.price{display:block;color:#192219;font-size:1.65rem;font-weight:950;margin-top:2px;letter-spacing:-.035em}.coupon{background:#fff8d5;border:1px dashed #e9c62b;padding:8px 9px;border-radius:9px;font-weight:850;font-size:.81rem;margin-top:9px}.cta{display:block;text-align:center;color:#fff;background:linear-gradient(135deg,var(--green2),var(--green));font-weight:950;text-decoration:none;border-radius:12px;padding:14px;margin-top:15px;box-shadow:0 8px 18px #4faa1533;transition:.18s}.cta:hover{filter:brightness(.95);transform:translateY(-1px)}.empty,.error{background:#fff;border:1px solid var(--line);padding:34px;border-radius:18px;text-align:center}.error{color:#a11d2a;border-color:#f1b9be;background:#fff5f6}footer{background:#0b1015;text-align:center;color:#aeb7bf;padding:38px 15px 42px}footer b{color:var(--yellow)}@media(max-width:700px){.site-header{padding:0 14px 82px}.nav{min-height:90px}.brand-logo{width:170px;height:72px}.nav-badge{font-size:.72rem}.hero{margin-top:18px}.hero h1{font-size:2.65rem}.trust{gap:9px 14px}.search-panel{padding:11px;border-radius:19px}.searchbox{flex-direction:column}.searchbox button{height:52px}.grid{grid-template-columns:minmax(0,1fr);gap:17px}main{padding:0 12px}.section-head{display:block;margin-top:32px}.photo{height:245px;min-height:245px;max-height:245px;padding:14px}.content{min-height:0;padding:17px}.offer-card{width:100%}}
</style></head><body><header class="site-header"><nav class="nav"><img class="brand-logo" src="/logo.jpeg" alt="Promo do Geissito"><span class="nav-badge">Ofertas atualizadas todos os dias</span></nav><div class="hero"><span class="eyebrow">Economia de verdade</span><h1>As melhores promoções, <span>você encontra aqui.</span></h1><p>Pesquise entre milhares de ofertas das principais lojas e aproveite preços que realmente valem a pena.</p><div class="trust"><span>Links seguros</span><span>Cupons selecionados</span><span>Grandes lojas</span></div></div></header><main><div class="search-panel"><form class="searchbox" id="form"><input id="query" autofocus placeholder="Qual produto você está procurando?" autocomplete="off"><button id="search">Buscar promoções</button></form><div class="examples"><span class="chip" data-q="air fryer">🔥 Air fryer</span><span class="chip" data-q="TV 50">📺 TV 50</span><span class="chip" data-q="tênis masculino">👟 Tênis masculino</span></div></div><div class="section-head"><div class="section-title"><h2 id="sectionHeading">Promoções em destaque</h2><p id="sectionSub">Ofertas escolhidas para você economizar hoje.</p></div><div id="status">Carregando promoções…</div></div><section id="results"></section></main><footer>Preços e disponibilidade podem mudar a qualquer momento.<br><br><b>Promo do Geissito: achou promoção, achou economia!</b></footer>
<script>
const form=document.querySelector('#form'),input=document.querySelector('#query'),button=document.querySelector('#search'),status=document.querySelector('#status'),results=document.querySelector('#results'),sectionHeading=document.querySelector('#sectionHeading'),sectionSub=document.querySelector('#sectionSub');const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const cards=offers=>'<div class="grid">'+offers.map(o=>`<article class="offer-card"><div class="photo">${o.image?`<img src="${esc(o.image)}" alt="${esc(o.title)}" loading="lazy">`:''}${o.discount?`<span class="discount">-${o.discount}%</span>`:''}</div><div class="content"><span class="store">${esc(o.store)}</span><h2>${esc(o.title)}</h2><div class="prices">${o.old_price?`<span class="old">De ${esc(o.old_price)}</span>`:''}<span class="price">${esc(o.price)}</span>${o.coupon?`<div class="coupon">Cupom: ${esc(o.coupon)}</div>`:''}</div><a class="cta" href="${esc(o.url)}" target="_blank" rel="noopener sponsored nofollow">Ver promoção</a></div></article>`).join('')+'</div>';async function load(url,initial=false){button.disabled=true;results.innerHTML='';sectionHeading.textContent=initial?'Promoções em destaque':'Resultados da sua busca';sectionSub.textContent=initial?'Ofertas escolhidas para você economizar hoje.':'As melhores ofertas encontradas para o produto pesquisado.';status.innerHTML=`<span class="loading"><span class="spinner"></span>${initial?'Carregando promoções em destaque…':'Consultando as ofertas…'}</span>`;try{const r=await fetch(url);const d=await r.json();if(!r.ok)throw new Error(d.error||'Falha ao carregar');status.textContent=initial?`${d.indexed} promoções disponíveis`:`${d.count} resultado(s) em ${d.indexed} ofertas.`;results.innerHTML=d.offers.length?cards(d.offers):'<div class="empty">Nenhuma oferta correspondente foi encontrada agora.</div>'}catch(e){status.textContent='';results.innerHTML=`<div class="error"><b>Não foi possível carregar as ofertas.</b><br>${esc(e.message)}<br><br>Tente novamente.</div>`}finally{button.disabled=false}}async function search(q){q=(q||'').trim();if(q.length<2){status.textContent='Digite pelo menos 2 caracteres.';return}input.value=q;return load('/api/search?q='+encodeURIComponent(q))}form.addEventListener('submit',e=>{e.preventDefault();search(input.value)});document.querySelectorAll('.chip').forEach(c=>c.addEventListener('click',()=>search(c.dataset.q)));load('/api/featured',true);
</script></body></html>'''


class Handler(BaseHTTPRequestHandler):
    def send_bytes(self, body: bytes, content_type: str, status: int = 200) -> None:
        self.send_response(status); self.send_header("Content-Type", content_type); self.send_header("Content-Length", str(len(body))); self.send_header("Cache-Control", "no-store"); self.end_headers(); self.wfile.write(body)

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        if parsed.path == "/": self.send_bytes(HTML.encode(), "text/html; charset=utf-8"); return
        if parsed.path == "/logo.jpeg":
            logo_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "logo-promo-do-geissito.jpeg")
            try:
                with open(logo_path, "rb") as logo_file: self.send_bytes(logo_file.read(), "image/jpeg")
            except OSError: self.send_bytes(b"Not found", "text/plain", 404)
            return
        if parsed.path == "/api/search":
            query = (parse_qs(parsed.query).get("q") or [""])[0].strip()
            try:
                offers, stats = INDEX.search(query, limit=24)
                data = {"count": len(offers), "indexed": stats.get("accepted", 0), "offers": [{"title": o.title, "store": o.store, "price": brl(o.price), "old_price": brl(o.old_price) if o.old_price else None, "discount": o.discount, "coupon": o.coupon, "image": o.image, "url": o.affiliate_url} for o in offers]}
                self.send_bytes(json.dumps(data, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            except SourceError as exc: self.send_bytes(json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8", 502)
            return
        if parsed.path == "/api/featured":
            try:
                offers, stats = INDEX.featured(limit=12)
                data = {"count": len(offers), "indexed": stats.get("accepted", 0), "offers": [{"title": o.title, "store": o.store, "price": brl(o.price), "old_price": brl(o.old_price) if o.old_price else None, "discount": o.discount, "coupon": o.coupon, "image": o.image, "url": o.affiliate_url} for o in offers]}
                self.send_bytes(json.dumps(data, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            except SourceError as exc: self.send_bytes(json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8", 502)
            return
        self.send_bytes(b"Not found", "text/plain", 404)

    def log_message(self, format: str, *args) -> None: return


if __name__ == "__main__":
    root = os.path.dirname(os.path.abspath(__file__)); pid_path = os.path.join(root, ".promo.pid")
    with open(pid_path, "w", encoding="ascii") as f: f.write(str(os.getpid()))
    server = ThreadingHTTPServer((os.getenv("HOST", "127.0.0.1"), int(os.getenv("PORT", "7860"))), Handler)
    threading.Thread(target=lambda: INDEX.refresh(), daemon=True).start()
    try: server.serve_forever()
    finally:
        server.server_close()
        try: os.remove(pid_path)
        except OSError: pass
